  "client.setupTxnPinTitle": { en: "Set up your transaction PIN", pidgin: "Set up your transaction PIN", ha: "Saita PIN na mu'amalarka", ig: "Debe PIN azụmahịa gị", yo: "Ṣètò PIN ìdúnàádúrà rẹ" },
  "client.setupTxnPinBody": { en: "For your security, a transaction PIN is required before you can withdraw, deposit, or move money. It only takes a minute.", pidgin: "For your safety, you need transaction PIN before you fit withdraw, deposit or move money. E no go pass one minute.", ha: "Don tsaronka, ana buƙatar PIN na mu'amala kafin ka iya cirewa, ajiya, ko tura kuɗi. Minti ɗaya kawai yake ɗauka.", ig: "Maka nchekwa gị, achọrọ PIN azụmahịa tupu i nwee ike iwepụ, itinye ma ọ bụ ibufe ego. Ọ na-ewe naanị otu nkeji.", yo: "Fún ààbò rẹ, o nílò PIN ìdúnàádúrà kí o tó lè gba owó jáde, fi owó sílẹ̀, tàbí gbé owó. Ìṣẹ́jú kan péré ni." },
