  "client.pending": { en: "Pending", pidgin: "Pending", ha: "Ana jira", ig: "Na-echere", yo: "Ó ń dúró" },
  "client.esusuCommittedPaid": { en: "{amt} still committed to this round — your payout is already paid, this funds other members' turns", pidgin: "{amt} still dey this round — dem don pay you already, this one na for other members' turn", ha: "{amt} har yanzu yana cikin wannan zagaye — an riga an biya ka, wannan yana biyan juyin sauran membobi", ig: "{amt} ka nọ n'agba a — akwụọla gị ụgwọ gị, nke a na-akwụ maka oge ndị otu ndị ọzọ", yo: "{amt} ṣì wà nínú àyípo yìí — wọ́n ti san tìrẹ, èyí ń san fún àyípo àwọn ọmọ ẹgbẹ́ mìíràn" },
  "client.esusuLockedTurn": { en: "{amt} of your contributions locked in this circle — released on your payout turn", pidgin: "{amt} of your contributions dey locked for this circle — e go release for your payout turn", ha: "{amt} na gudummawarka a kulle a wannan da'ira — za a sake shi a juyinka na karɓa", ig: "{amt} n'ime ntinye gị kpọchiri n'okirikiri a — a ga-ahapụ ya n'oge nnata gị", yo: "{amt} nínú owó tí o dá ti wà ní títì nínú àyíká yìí — a ó tú u sílẹ̀ nígbà tí ó bá kàn ọ́" },
  "client.enterValidAmount": { en: "Please enter a valid amount.", pidgin: "Abeg enter correct amount.", ha: "Da fatan shigar da adadi mai inganci.", ig: "Biko tinye ego ziri ezi.", yo: "Jọ̀wọ́ tẹ iye owó tó tọ́." },
  "client.paidFromWallet": { en: "Paid from your KudiAI Wallet.", pidgin: "You don pay from your KudiAI Wallet.", ha: "An biya daga KudiAI Wallet ɗinka.", ig: "Akwụrụ ya site na KudiAI Wallet gị.", yo: "A ti san án láti KudiAI Wallet rẹ." },
  "client.useInstead": { en: "Use {amt} instead", pidgin: "Use {amt} instead", ha: "Yi amfani da {amt} maimakon haka", ig: "Jiri {amt} kama", yo: "Lo {amt} dípò rẹ̀" },
  "client.firstPaymentNote": { en: "Your first payment is ₦{min} — includes a one-time ₦{reg} registration. After today, every payment is ₦{exp}.", pidgin: "Your first payment na ₦{min} — e include one-time ₦{reg} registration. After today, every payment na ₦{exp}.", ha: "Biyanka na farko ₦{min} ne — ya haɗa da kuɗin rajista na lokaci ɗaya ₦{reg}. Bayan yau, kowane biya ₦{exp} ne.", ig: "Ịkwụ ụgwọ mbụ gị bụ ₦{min} — gụnyere ego ndebanye aha otu ugboro ₦{reg}. Mgbe taa gasịrị, ịkwụ ụgwọ ọ bụla bụ ₦{exp}.", yo: "Ìsanwó àkọ́kọ́ rẹ jẹ́ ₦{min} — ó ní owó ìforúkọsílẹ̀ ẹ̀ẹ̀kan ₦{reg} nínú. Lẹ́yìn òní, ìsanwó kọ̀ọ̀kan jẹ́ ₦{exp}." },
  "client.walletNotReady": { en: "Your KudiAI Wallet isn't ready yet", pidgin: "Your KudiAI Wallet never ready", ha: "KudiAI Wallet ɗinka bai shirya ba tukuna", ig: "KudiAI Wallet gị adịbeghị njikere", yo: "KudiAI Wallet rẹ kò tíì ṣetán" },
  "client.walletNotReadyBody": { en: "Contributions are paid from your wallet. Saving needs no ID number — opening a wallet needs your BVN or NIN, that's a CBN rule, not ours.", pidgin: "Na from your wallet you dey pay contribution. Saving no need ID number — to open wallet need your BVN or NIN, na CBN rule, no be our own.", ha: "Ana biyan gudummawa daga walat ɗinka. Ajiya ba ta buƙatar lambar shaida — buɗe walat yana buƙatar BVN ko NIN, wannan dokar CBN ce, ba tamu ba.", ig: "A na-akwụ ntinye ego site n'akpa ego gị. Nchekwa achọghị nọmba NJ — imeghe akpa ego chọrọ BVN ma ọ bụ NIN gị, nke ahụ bụ iwu CBN, ọ bụghị nke anyị.", yo: "Láti inú wálẹ́ẹ̀tì rẹ ni a ti ń san owó àjọ. Ìfowópamọ́ kò nílò nọ́ńbà ìdánimọ̀ — ṣíṣí wálẹ́ẹ̀tì nílò BVN tàbí NIN rẹ, òfin CBN ni, kì í ṣe tiwa." },
  "client.activateWallet": { en: "Activate wallet", pidgin: "Activate wallet", ha: "Kunna walat", ig: "Mee ka akpa ego rụọ ọrụ", yo: "Mú wálẹ́ẹ̀tì ṣiṣẹ́" },
