  "client.insufficientWallet": { en: "Insufficient wallet balance.", pidgin: "Money for wallet no reach.", ha: "Kuɗin walat bai isa ba.", ig: "Ego dị n'akpa ezughị.", yo: "Owó inú wálẹ́ẹ̀tì kò tó." },
