  "client.paidStraightPre": { en: "Paid straight to your", pidgin: "We go pay am straight to your", ha: "Ana biya kai tsaye zuwa", ig: "A na-akwụ ya ozugbo na", yo: "A óò san án tààrà sí" },
  "client.paidStraightPost": { en: "— no bank account to set up. Once approved, it lands in your wallet straight away.", pidgin: "— you no need set bank account. Once dem approve, e go land your wallet sharp sharp.", ha: "— babu buƙatar saita asusun banki. Da zarar an amince, zai shiga walat ɗinka nan take.", ig: "— ọ dịghị akaụntụ ụlọ akụ ị ga-edozi. Ozugbo akwadoro ya, ọ ga-abata n'akpa gị ozugbo.", yo: "— kò sí àkáǹtì báńkì láti ṣètò. Ní kété tí wọ́n bá fọwọ́ sí i, yóò wọ inú wálẹ́ẹ̀tì rẹ lẹ́sẹ̀kẹsẹ̀." },
  "client.walletNotActiveWithdraw": { en: "Your KudiAI wallet isn't active yet — activate it first so this can actually be paid out once approved.", pidgin: "Your KudiAI wallet never active — activate am first so dem fit pay you once dem approve.", ha: "KudiAI wallet ɗinka bai fara aiki ba tukuna — kunna shi da farko don a iya biyan wannan da zarar an amince.", ig: "KudiAI wallet gị amalitebeghị ọrụ — buru ụzọ mee ka ọ rụọ ọrụ ka e nwee ike ịkwụ ya ozugbo akwadoro ya.", yo: "KudiAI wallet rẹ kò tíì ṣiṣẹ́ — kọ́kọ́ mú un ṣiṣẹ́ kí a lè san owó yìí ní kété tí wọ́n bá fọwọ́ sí i." },
