  "client.termsSub": { en: "View the full terms of service", pidgin: "See the full terms of service", ha: "Duba cikakkun sharuɗɗan sabis", ig: "Lee usoro ọrụ zuru ezu", yo: "Wo gbogbo òfin iṣẹ́" },
