  "client.privacySub": { en: "How we collect and use your data", pidgin: "How we dey collect and use your data", ha: "Yadda muke tattarawa da amfani da bayananka", ig: "Otú anyị si anakọta ma jiri data gị", yo: "Bí a ṣe ń kó àti lo dátà rẹ" },
  "client.consentRecord": { en: "Your consent record", pidgin: "Your consent record", ha: "Bayanan amincewarka", ig: "Ndekọ nkwenye gị", yo: "Àkọsílẹ̀ ìfọwọ́sí rẹ" },
  "client.consentAccepted": { en: "You accepted T&C v{tnc} and Privacy Policy v{privacy} on {date}", pidgin: "You accept T&C v{tnc} and Privacy Policy v{privacy} on {date}", ha: "Ka amince da T&C v{tnc} da Manufar Sirri v{privacy} a ranar {date}", ig: "I nabatara T&C v{tnc} na Iwu Nzuzo v{privacy} na {date}", yo: "O gba T&C v{tnc} àti Ìlànà Àṣírí v{privacy} ní {date}" },
