  "client.poweredBy": { en: "Powered by AMAYA & Co. Technologies", pidgin: "Powered by AMAYA & Co. Technologies", ha: "AMAYA & Co. Technologies ne ke tallafawa", ig: "AMAYA & Co. Technologies na-akwado ya", yo: "Láti ọwọ́ AMAYA & Co. Technologies" },
  "client.allRights": { en: "All rights reserved © {year}", pidgin: "All rights reserved © {year}", ha: "Duk haƙƙoƙi a kiyaye © {year}", ig: "Ikike niile echekwara © {year}", yo: "Gbogbo ẹ̀tọ́ wà ní ìpamọ́ © {year}" },
  "client.neverLockWarn": { en: "Your app won't lock automatically. Anyone with access to your device can open it without a PIN.", pidgin: "Your app no go lock by itself. Anybody wey hold your phone fit open am without PIN.", ha: "Manhajarka ba za ta kulle da kanta ba. Duk wanda ya samu na'urarka zai iya buɗe ta ba tare da PIN ba.", ig: "Ngwa gị agaghị akpọchi onwe ya. Onye ọ bụla nwere ngwaọrụ gị nwere ike imeghe ya na-enweghị PIN.", yo: "Áàpù rẹ kò ní tì fúnra rẹ̀. Ẹnikẹ́ni tó bá ní ẹ̀rọ rẹ lè ṣí i láìsí PIN." },
  "client.enterCurrentPin": { en: "Enter current PIN", pidgin: "Enter current PIN", ha: "Shigar da PIN na yanzu", ig: "Tinye PIN ugbu a", yo: "Tẹ PIN lọ́wọ́lọ́wọ́" },
  "client.enterAppUnlockPin": { en: "Enter your 6-digit app unlock PIN", pidgin: "Enter your 6-digit app unlock PIN", ha: "Shigar da PIN ɗinka mai lambobi 6 na buɗe manhaja", ig: "Tinye PIN mmeghe ngwa gị nwere ọnụọgụ 6", yo: "Tẹ PIN ìṣí áàpù oní-nọ́ńbà 6 rẹ" },
  "client.enterNewPin": { en: "Enter new PIN", pidgin: "Enter new PIN", ha: "Shigar da sabon PIN", ig: "Tinye PIN ọhụrụ", yo: "Tẹ PIN tuntun" },
  "client.setYourPin": { en: "Set your PIN", pidgin: "Set your PIN", ha: "Saita PIN ɗinka", ig: "Debe PIN gị", yo: "Ṣètò PIN rẹ" },
  "client.chooseUnlockPin": { en: "Choose a 6-digit unlock PIN for this app", pidgin: "Choose 6-digit unlock PIN for this app", ha: "Zaɓi PIN mai lambobi 6 don buɗe wannan manhaja", ig: "Họrọ PIN mmeghe nwere ọnụọgụ 6 maka ngwa a", yo: "Yan PIN ìṣí oní-nọ́ńbà 6 fún áàpù yìí" },
  "client.confirmNewPin": { en: "Confirm new PIN", pidgin: "Confirm new PIN", ha: "Tabbatar da sabon PIN", ig: "Kwado PIN ọhụrụ", yo: "Jẹ́rìísí PIN tuntun" },
  "client.enterNewPinAgain": { en: "Enter your new PIN one more time", pidgin: "Enter your new PIN one more time", ha: "Shigar da sabon PIN ɗinka sau ɗaya kuma", ig: "Tinye PIN ọhụrụ gị otu ugboro ọzọ", yo: "Tẹ PIN tuntun rẹ lẹ́ẹ̀kan sí i" },
  "client.enterCurrentTxnPin": { en: "Enter current transaction PIN", pidgin: "Enter current transaction PIN", ha: "Shigar da PIN na mu'amala na yanzu", ig: "Tinye PIN azụmahịa ugbu a", yo: "Tẹ PIN ìdúnàádúrà lọ́wọ́lọ́wọ́" },
  "client.verifyIdentityTxn": { en: "Verify your identity before changing your transaction PIN", pidgin: "Confirm say na you before you change your transaction PIN", ha: "Tabbatar da kai kafin ka canza PIN na mu'amala", ig: "Kwado onye ị bụ tupu ị gbanwee PIN azụmahịa gị", yo: "Jẹ́rìísí ìdánimọ̀ rẹ kí o tó yí PIN ìdúnàádúrà rẹ padà" },
  "client.enterOtp": { en: "Enter OTP", pidgin: "Enter OTP", ha: "Shigar da OTP", ig: "Tinye OTP", yo: "Tẹ OTP" },
  "client.otpSentEmail": { en: "We sent a 6-digit code to your registered email", pidgin: "We don send 6-digit code to your email", ha: "Mun aika lamba mai lambobi 6 zuwa imel ɗinka", ig: "Anyị zigara koodu nwere ọnụọgụ 6 na email gị", yo: "A ti fi kóòdù oní-nọ́ńbà 6 ránṣẹ́ sí ímeèlì rẹ" },
  "client.setNewTxnPin": { en: "Set new transaction PIN", pidgin: "Set new transaction PIN", ha: "Saita sabon PIN na mu'amala", ig: "Debe PIN azụmahịa ọhụrụ", yo: "Ṣètò PIN ìdúnàádúrà tuntun" },
  "client.chooseTxnPin4": { en: "Choose a 4-digit PIN for authorising transactions", pidgin: "Choose 4-digit PIN to approve transactions", ha: "Zaɓi PIN mai lambobi 4 don amincewa da mu'amaloli", ig: "Họrọ PIN nwere ọnụọgụ 4 maka ikwado azụmahịa", yo: "Yan PIN oní-nọ́ńbà 4 fún fífọwọ́sí ìdúnàádúrà" },
  "client.enterNewTxnPinAgain": { en: "Enter your new transaction PIN once more", pidgin: "Enter your new transaction PIN one more time", ha: "Shigar da sabon PIN na mu'amala sau ɗaya kuma", ig: "Tinye PIN azụmahịa ọhụrụ gị ọzọ", yo: "Tẹ PIN ìdúnàádúrà tuntun rẹ lẹ́ẹ̀kan sí i" },
  "client.faq": { en: "FAQ", pidgin: "FAQ", ha: "Tambayoyi", ig: "Ajụjụ", yo: "Ìbéèrè" },
