  "client.selectLga": { en: "Select LGA…", pidgin: "Choose LGA…", ha: "Zaɓi Ƙaramar Hukuma…", ig: "Họrọ LGA…", yo: "Yan Ìjọba Ìbílẹ̀…" },
  "client.stateFirst": { en: "State first", pidgin: "Choose State first", ha: "Jiha da farko", ig: "Steeti buru ụzọ", yo: "Ìpínlẹ̀ lákọ̀ọ́kọ́" },
  "client.selectWard": { en: "Select Ward…", pidgin: "Choose Ward…", ha: "Zaɓi Mazaɓa…", ig: "Họrọ Wọọdụ…", yo: "Yan Wọ́ọ̀dù…" },
  "client.lgaFirst": { en: "LGA first", pidgin: "Choose LGA first", ha: "Ƙaramar Hukuma da farko", ig: "LGA buru ụzọ", yo: "Ìjọba Ìbílẹ̀ lákọ̀ọ́kọ́" },
  "client.kinNamePh": { en: "Next of kin name", pidgin: "Next of kin name", ha: "Sunan makusanci", ig: "Aha onye ikwu kacha nso", yo: "Orúkọ ẹbí tímọ́tímọ́" },
  "client.kinAddressPh": { en: "Next of kin address", pidgin: "Next of kin address", ha: "Adireshin makusanci", ig: "Adreesị onye ikwu kacha nso", yo: "Àdírẹ́sì ẹbí tímọ́tímọ́" },
  "client.activating": { en: "Activating…", pidgin: "E dey activate…", ha: "Ana kunnawa…", ig: "Ọ na-eme ka ọ rụọ ọrụ…", yo: "Ó ń mú un ṣiṣẹ́…" },
  "client.balance": { en: "Balance", pidgin: "Balance", ha: "Ragowar kuɗi", ig: "Ego fọdụrụ", yo: "Iye owó" },
  "client.reverifyBvnTitle": { en: "Please reverify your BVN", pidgin: "Abeg verify your BVN again", ha: "Da fatan sake tabbatar da BVN ɗinka", ig: "Biko kwado BVN gị ọzọ", yo: "Jọ̀wọ́ tún BVN rẹ jẹ́rìísí" },
  "client.reverifyBvnBody": { en: "We've added real BVN verification for wallet security. Your wallet keeps working normally, but please reverify to stay in good standing.", pidgin: "We don add real BVN verification for wallet security. Your wallet go still work normal, but abeg verify again make everything dey correct.", ha: "Mun ƙara ainihin tabbatar da BVN don tsaron walat. Walat ɗinka zai ci gaba da aiki yadda ya kamata, amma da fatan ka sake tabbatarwa don ka kasance cikin tsari.", ig: "Anyị agbakwunyela ezigbo nkwenye BVN maka nchekwa akpa ego. Akpa ego gị ga-aga n'ihu na-arụ ọrụ, mana biko kwado ọzọ ka ị nọrọ n'ọnọdụ ọma.", yo: "A ti fi ìjẹ́rìísí BVN gidi kún un fún ààbò wálẹ́ẹ̀tì. Wálẹ́ẹ̀tì rẹ yóò máa ṣiṣẹ́ déédéé, ṣùgbọ́n jọ̀wọ́ tún jẹ́rìísí kí o lè wà ní ipò rere." },
  "client.reverifyNow": { en: "Reverify now", pidgin: "Verify again now", ha: "Sake tabbatarwa yanzu", ig: "Kwado ọzọ ugbu a", yo: "Tún jẹ́rìísí báyìí" },
  "client.bvn11Ph": { en: "11-digit BVN", pidgin: "11-digit BVN", ha: "BVN mai lambobi 11", ig: "BVN nwere ọnụọgụ 11", yo: "BVN oní-nọ́ńbà 11" },
  "client.submit": { en: "Submit", pidgin: "Submit", ha: "Aika", ig: "Zipu", yo: "Fi ránṣẹ́" },
  "client.repeatTransfers": { en: "Repeat transfers", pidgin: "Repeat transfers", ha: "Tura kuɗi mai maimaitawa", ig: "Ịnyefe ego na-emegharị", yo: "Ìfiránṣẹ́ àtúnṣe" },
  "client.paused": { en: "Paused", pidgin: "Paused", ha: "An dakata", ig: "Akwụsịtụrụ", yo: "Ti dá dúró" },
