  "client.cancelRepeatQ": { en: "Cancel this repeat transfer to {name}?", pidgin: "Cancel this repeat transfer to {name}?", ha: "A soke wannan tura kuɗi mai maimaitawa zuwa {name}?", ig: "Kagbuo ịnyefe ego a na-emegharị gaa {name}?", yo: "Fagilé ìfiránṣẹ́ àtúnṣe yìí sí {name}?" },
  "client.transactions": { en: "Transactions", pidgin: "Transactions", ha: "Mu'amaloli", ig: "Azụmahịa", yo: "Àwọn ìdúnàádúrà" },
  "client.statementArrow": { en: "Statement →", pidgin: "Statement →", ha: "Bayanin asusu →", ig: "Nkwupụta →", yo: "Ìwé àkọsílẹ̀ →" },
  "client.noWalletActivity": { en: "No wallet activity yet.", pidgin: "Nothing don happen for wallet yet.", ha: "Babu wani aiki a walat tukuna.", ig: "Enweghị ihe omume n'akpa ego ugbu a.", yo: "Kò sí ìṣe kankan nínú wálẹ́ẹ̀tì síbẹ̀." },
  "client.upToDate": { en: "Up to date", pidgin: "Everything don update", ha: "An sabunta komai", ig: "Ihe niile dị ọhụrụ", yo: "Ohun gbogbo ti wà ní ìmúdójúìwọ̀n" },
  "client.offersForMembers": { en: "Offers for Members", pidgin: "Offers for Members", ha: "Tayi ga Membobi", ig: "Onyinye maka Ndị Otu", yo: "Àwọn Ìpèsè fún Ọmọ Ẹgbẹ́" },
  "client.loadFailedTitle": { en: "Couldn't load your data", pidgin: "We no fit load your data", ha: "An kasa loda bayananka", ig: "Enweghị ike ibugo data gị", yo: "A kò lè gbé dátà rẹ wá" },
  "client.loadFailedBody": { en: "Check your connection and try again.", pidgin: "Check your network and try again.", ha: "Duba haɗinka ka sake gwadawa.", ig: "Lelee njikọ gị ma nwaa ọzọ.", yo: "Ṣàyẹ̀wò ìsopọ̀ rẹ kí o tún gbìyànjú." },
  "client.retry": { en: "Retry", pidgin: "Try again", ha: "Sake gwadawa", ig: "Nwaa ọzọ", yo: "Tún gbìyànjú" },
  "client.dailyFallback": { en: "Keep it up{name}! Every contribution you make brings you one step closer to your savings goal — stay consistent and you'll get there!", pidgin: "Keep am up{name}! Every contribution wey you make dey bring you one step near your savings goal — no stop and you go reach there!", ha: "Ci gaba haka{name}! Kowace gudummawa da ka bayar tana kusantar da kai mataki ɗaya zuwa burin ajiyarka — ka dage za ka kai!", ig: "Gaa n'ihu otu a{name}! Ntinye ego ọ bụla ị na-eme na-eme ka ị bịaruo ebumnuche nchekwa gị nso otu nzọụkwụ — nọgide na ya, ị ga-eru ya!", yo: "Máa bá a lọ{name}! Gbogbo ìdáwó tí o bá ṣe ń mú ọ sún mọ́ àfojúsùn ìfowópamọ́ rẹ ní ìgbésẹ̀ kan — dúró ṣinṣin, ìwọ yóò dé ibẹ̀!" },
  "client.aiGreet1": { en: "I'm **KudiAI**, your Ajo savings assistant.", pidgin: "Na me be **KudiAI**, your Ajo savings assistant.", ha: "Ni ne **KudiAI**, mataimakin ajiyar Ajo ɗinka.", ig: "Abụ m **KudiAI**, onye inyeaka nchekwa Ajo gị.", yo: "Èmi ni **KudiAI**, olùrànlọ́wọ́ ìfowópamọ́ Ajo rẹ." },
  "client.aiGreet2": { en: "I know your balance, contributions, and savings history. Ask me anything!", pidgin: "I sabi your balance, contributions and savings history. Ask me anything!", ha: "Na san ragowar kuɗinka, gudummawarka, da tarihin ajiyarka. Tambaye ni komai!", ig: "Amaara m ego gị, ntinye gị na akụkọ nchekwa gị. Jụọ m ihe ọ bụla!", yo: "Mo mọ iye owó rẹ, ìdáwó rẹ, àti ìtàn ìfowópamọ́ rẹ. Bi mí ní ohunkóhun!" },
  "client.chipTips": { en: "{base} Tips", pidgin: "{base} Tips", ha: "Shawarwarin {base}", ig: "Ndụmọdụ {base}", yo: "Ìmọ̀ràn {base}" },
  "client.searchOrAsk": { en: "Search or ask anything…", pidgin: "Search or ask anything…", ha: "Bincika ko tambayi komai…", ig: "Chọọ ma ọ bụ jụọ ihe ọ bụla…", yo: "Wá tàbí bèèrè ohunkóhun…" },
